export default {"html":"<p data-line=\"0\" class=\"code-line\">Angular v17's <code>withComponentInputBinding</code> combined with signal inputs dramatically improves how you handle route parameters. This article shows migration patterns from the old approach to the new one. (Yes, this is late—but I had a project that kept putting migration off, and I wrote this as reference material for generative AI.)</p>\n<h2 id=\"comparing-the-old-and-new-approaches\" data-line=\"2\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#comparing-the-old-and-new-approaches\" aria-hidden=\"true\"></a> Comparing the old and new approaches</h2>\n<h2 id=\"1.-getting-params-from-activatedroute\" data-line=\"4\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#1.-getting-params-from-activatedroute\" aria-hidden=\"true\"></a> 1. Getting params from ActivatedRoute</h2>\n<p data-line=\"6\" class=\"code-line\">To get params from <code>ActivatedRoute</code>, you either subscribe to <code>paramMap</code> or read <code>snapshot.paramMap</code>.</p>\n<h3 id=\"old-approach\" data-line=\"8\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#old-approach\" aria-hidden=\"true\"></a> Old approach</h3>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"9\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">  // ...</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> UserDetailComponent</span><span style=\"color:#B392F0\"> implement</span><span style=\"color:#B392F0\"> OnInit</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  userId</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> string</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  route</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> inject</span><span style=\"color:#E1E4E8\">(ActivatedRoute);</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  ngOnInit</span><span style=\"color:#E1E4E8\">() {</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">    // Pattern paramMap</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.route.paramMap.</span><span style=\"color:#B392F0\">subscribe</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">params</span><span style=\"color:#F97583\"> =&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">      this</span><span style=\"color:#E1E4E8\">.userId </span><span style=\"color:#F97583\">=</span><span style=\"color:#E1E4E8\"> params[</span><span style=\"color:#9ECBFF\">'id'</span><span style=\"color:#E1E4E8\">];</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    });</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">    // Pattern snapshot</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.userId </span><span style=\"color:#F97583\">=</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.route.snapshot.paramMap.</span><span style=\"color:#B392F0\">get</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'id'</span><span style=\"color:#E1E4E8\">);</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><h3 id=\"new-approach\" data-line=\"29\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#new-approach\" aria-hidden=\"true\"></a> New approach</h3>\n<p data-line=\"31\" class=\"code-line\">With <code>withComponentInputBinding</code>, you can write:</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"33\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">  // ...</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> UserDetailComponent</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  userId</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> input</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#79B8FF\">string</span><span style=\"color:#E1E4E8\">&gt;();</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"42\" class=\"code-line\">This feature binds the following directly to component inputs:</p>\n<ul data-line=\"44\" class=\"code-line\">\n<li data-line=\"44\" class=\"code-line\">Query parameters</li>\n<li data-line=\"45\" class=\"code-line\">Path and matrix parameters</li>\n<li data-line=\"46\" class=\"code-line\">Static route data</li>\n<li data-line=\"47\" class=\"code-line\">Resolver data</li>\n</ul>\n<h2 id=\"2.-when-you-subscribed-to-paramsmap-for-other-work\" data-line=\"49\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#2.-when-you-subscribed-to-paramsmap-for-other-work\" aria-hidden=\"true\"></a> 2. When you subscribed to paramsMap for other work</h2>\n<p data-line=\"51\" class=\"code-line\">You may also have run other logic whenever <code>paramsMap</code> changed.</p>\n<h3 id=\"old-approach-1\" data-line=\"53\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#old-approach-1\" aria-hidden=\"true\"></a> Old approach</h3>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"54\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">  // ...</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> UserDetailComponent</span><span style=\"color:#B392F0\"> implement</span><span style=\"color:#B392F0\"> OnInit</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  route</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> inject</span><span style=\"color:#E1E4E8\">(ActivatedRoute);</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  userService</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> inject</span><span style=\"color:#E1E4E8\">(UserService);</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  userId</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> string</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  userData</span><span style=\"color:#F97583\">:</span><span style=\"color:#B392F0\"> IUser</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#B392F0\">  ngOnInit</span><span style=\"color:#E1E4E8\">() {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.route.paramMap.</span><span style=\"color:#B392F0\">subscribe</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">params</span><span style=\"color:#F97583\"> =&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">      this</span><span style=\"color:#E1E4E8\">.userId </span><span style=\"color:#F97583\">=</span><span style=\"color:#E1E4E8\"> params.</span><span style=\"color:#B392F0\">get</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'id'</span><span style=\"color:#E1E4E8\">)</span><span style=\"color:#F97583\">!</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">      this</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">loadUserData</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    });</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">  private</span><span style=\"color:#B392F0\"> loadUserData</span><span style=\"color:#E1E4E8\">() {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">    this</span><span style=\"color:#E1E4E8\">.userService.</span><span style=\"color:#B392F0\">getUser</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#79B8FF\">this</span><span style=\"color:#E1E4E8\">.userId).</span><span style=\"color:#B392F0\">subscribe</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">data</span><span style=\"color:#F97583\"> =&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">      this</span><span style=\"color:#E1E4E8\">.userData </span><span style=\"color:#F97583\">=</span><span style=\"color:#E1E4E8\"> data;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    });</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><h3 id=\"new-approach-1\" data-line=\"79\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#new-approach-1\" aria-hidden=\"true\"></a> New approach</h3>\n<p data-line=\"81\" class=\"code-line\">Use an <code>effect</code> to react to signal inputs. Note that when no matching route key exists, the input is set to <code>undefined</code>. That prevents stale values when route data is removed (for example, when a query parameter is dropped).</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"83\"><span class=\"line\"><span style=\"color:#E1E4E8\">@</span><span style=\"color:#B392F0\">Component</span><span style=\"color:#E1E4E8\">({</span></span>\n<span class=\"line\"><span style=\"color:#a0aab5\">  // ...</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">})</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">export</span><span style=\"color:#F97583\"> class</span><span style=\"color:#B392F0\"> UserDetailComponent</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  route</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> inject</span><span style=\"color:#E1E4E8\">(ActivatedRoute);</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  userService</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> inject</span><span style=\"color:#E1E4E8\">(UserService);</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  userId</span><span style=\"color:#F97583\"> =</span><span style=\"color:#B392F0\"> input</span><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#79B8FF\">string</span><span style=\"color:#E1E4E8\">&gt;();</span></span>\n<span class=\"line\"><span style=\"color:#FFAB70\">  userData</span><span style=\"color:#F97583\">:</span><span style=\"color:#B392F0\"> IUser</span><span style=\"color:#E1E4E8\">;</span></span>\n<span class=\"line\"></span>\n<span class=\"line\"><span style=\"color:#F97583\">  constructor</span><span style=\"color:#E1E4E8\">() {</span></span>\n<span class=\"line\"><span style=\"color:#B392F0\">    effect</span><span style=\"color:#E1E4E8\">(() </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">      const</span><span style=\"color:#79B8FF\"> id</span><span style=\"color:#F97583\"> =</span><span style=\"color:#79B8FF\"> this</span><span style=\"color:#E1E4E8\">.</span><span style=\"color:#B392F0\">userId</span><span style=\"color:#E1E4E8\">();</span></span>\n<span class=\"line\"><span style=\"color:#F97583\">      if</span><span style=\"color:#E1E4E8\"> (id) {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">        this</span><span style=\"color:#E1E4E8\">.userService.</span><span style=\"color:#B392F0\">getUser</span><span style=\"color:#E1E4E8\">(id).</span><span style=\"color:#B392F0\">subscribe</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#FFAB70\">data</span><span style=\"color:#F97583\"> =&gt;</span><span style=\"color:#E1E4E8\"> {</span></span>\n<span class=\"line\"><span style=\"color:#79B8FF\">          this</span><span style=\"color:#E1E4E8\">.userData </span><span style=\"color:#F97583\">=</span><span style=\"color:#E1E4E8\"> data;</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">        });</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">      }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">    })</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">  }</span></span>\n<span class=\"line\"><span style=\"color:#E1E4E8\">}</span></span>\n<span class=\"line\"></span></code></pre></div><h2 id=\"benefits-of-the-new-approach\" data-line=\"106\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#benefits-of-the-new-approach\" aria-hidden=\"true\"></a> Benefits of the new approach</h2>\n<p data-line=\"108\" class=\"code-line\">The old approach required injecting <code>ActivatedRoute</code> and subscribing. The new approach needs only signal inputs. Code becomes more declarative and type-safe.</p>\n<p data-line=\"110\" class=\"code-line\">Signal inputs also simplify component inputs and make tests easier to write. When route parameter changes should trigger other work, <code>effect</code> keeps the code declarative.</p>\n<h2 id=\"summary\" data-line=\"112\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#summary\" aria-hidden=\"true\"></a> Summary</h2>\n<p data-line=\"114\" class=\"code-line\"><code>withComponentInputBinding</code> with signal inputs greatly improves route parameter handling. Code is shorter, types are safer, and performance improves—a win on all three fronts.</p>\n<p data-line=\"116\" class=\"code-line\">New projects should use it by default, and existing projects are worth migrating incrementally. Components with complex route parameter logic should show the benefit clearly.</p>\n","headings":[{"id":"comparing-the-old-and-new-approaches","text":"Comparing the old and new approaches","level":2},{"id":"1.-getting-params-from-activatedroute","text":"1. Getting params from ActivatedRoute","level":2},{"id":"old-approach","text":"Old approach","level":3},{"id":"new-approach","text":"New approach","level":3},{"id":"2.-when-you-subscribed-to-paramsmap-for-other-work","text":"2. When you subscribed to paramsMap for other work","level":2},{"id":"old-approach-1","text":"Old approach","level":3},{"id":"new-approach-1","text":"New approach","level":3},{"id":"benefits-of-the-new-approach","text":"Benefits of the new approach","level":2},{"id":"summary","text":"Summary","level":2}]} as const;
